import{_ as r,c as o,o as a,ag as t}from"./chunks/framework.DfL_BkQ-.js";const p=JSON.parse(`{"title":"Mini-Program Sources","description":"Where nPlyr's mini-programs and rule sources come from, and how to add your own.","frontmatter":{"title":"Mini-Program Sources","description":"Where nPlyr's mini-programs and rule sources come from, and how to add your own.","layout":"doc"},"headers":[],"relativePath":"guide/miniapp-sources.md","filePath":"guide/miniapp-sources.md","lastUpdated":1791309864000}`),i={name:"guide/miniapp-sources.md"};function s(n,e,c,d,l,m){return a(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="mini-program-sources" tabindex="-1">Mini-Program Sources <a class="header-anchor" href="#mini-program-sources" aria-label="Permalink to &quot;Mini-Program Sources&quot;">​</a></h1><p>This page is part of the <strong>Mini-Programs</strong> guide section — the catalog of community mini-programs and rule sources that nPlyr can import. nPlyr does <strong>not</strong> ship with a fixed list of video sources; instead you bring your own, and the in-app manager imports them.</p><h2 id="where-sources-come-from" tabindex="-1">Where sources come from <a class="header-anchor" href="#where-sources-come-from" aria-label="Permalink to &quot;Where sources come from&quot;">​</a></h2><ul><li><strong>The hikerView ecosystem.</strong> nPlyr is compatible with the same share texts and JSON that the Android app uses, so existing community rules import directly.</li><li><strong>Cloud shares.</strong> nPlyr supports the cloud backends <strong>TextDB</strong> (云2), <code>cmd.im</code> (302 redirect, 云5) and <strong>pasteme</strong> (云6), so rules hosted there can be subscribed to in one step.</li><li><strong>Your own.</strong> Write or adapt a rule and import it — see the <a href="/guide/miniapps.html">Mini-Programs overview</a> and the <a href="/guide/miniapp-compatibility.html">Compatibility</a> boundary first.</li></ul><h2 id="adding-a-source" tabindex="-1">Adding a source <a class="header-anchor" href="#adding-a-source" aria-label="Permalink to &quot;Adding a source&quot;">​</a></h2><ol><li>Open <strong>Mini-Programs</strong> in nPlyr (the manager window on macOS, a page on iOS).</li><li>Choose <strong>Add</strong> and paste the share text / JSON, or pick a cloud source to subscribe.</li><li>The program appears in the home top row — drag to reorder.</li></ol><p>A free tier caps how many programs you can keep imported at once; a one-time unlock removes the cap.</p><h2 id="compatibility-matters" tabindex="-1">Compatibility matters <a class="header-anchor" href="#compatibility-matters" aria-label="Permalink to &quot;Compatibility matters&quot;">​</a></h2><p>Not every Android rule runs identically on nPlyr. nPlyr&#39;s engine is <strong>JavaScriptCore</strong>, not Java/Rhino, and only a curated subset of the Java API is emulated. Before relying on a source, check the <a href="/guide/miniapp-compatibility.html">Compatibility</a> page and report any rule that fails (include the rule name and the step it failed at).</p><blockquote><p>The catalog you browse here is community-curated. nPlyr is not the author of third-party mini-programs and does not vouch for their content — only install sources you trust.</p></blockquote>',10)])])}const h=r(i,[["render",s]]);export{p as __pageData,h as default};
